  /// Returns translation for [key] in the active language.
  /// Falls back to English, then the key itself.
  static String of(String key) {
    final code = localeController.value.languageCode;
    final entry = _all[key];
    if (entry == null) return key;
    return entry[code] ?? entry['en'] ?? key;
  }
}

/// `context.t('key')` shorthand — use inside build() methods.
extension TranslationsX on BuildContext {
  String t(String key) => Translations.of(key);
}
